declarations.code:
template <class G>

concept uniform_random_bit_generator =

    std::invocable<G &> && std::unsigned_integral<std::invoke_result_t<G &>> &&

    requires {
        { G::min() } -> std::same_as<std::invoke_result_t<G &>>;

        { G::max() } -> std::same_as<std::invoke_result_t<G &>>;

        requires std::bool_constant<(G::min() < G::max())>::value;
    };

examples.code:
#include <random>
#include <concepts>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::random_device source;
    static_assert(std::uniform_random_bit_generator<std::random_device>);
    auto value = source();
    assert(value >= source.min() && value <= source.max());
}
